"""股民的晚餐 首帧（H3 Image）。
用法：python3 出首帧.py <帧名...> --mode t2i|ref --machine xw|wj [--seeds 11,12]
帧名：A1 A2 A3 B1 B2 B3（文字或参考帧构图）、A4 B4（在 ../首帧/定稿/A3.png、B3.png 上改：关灯 / 管家换龙虾）
输出：../首帧/候选/<帧名>_<mode>_s<seed>...png
"""
import os, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__)); V = os.path.dirname(HERE)
S = os.environ.get("H3_SCRIPTS", os.path.normpath(os.path.join(HERE, "..", "..", "..", "scripts")))  # 技能仓库的 scripts/ 目录
REF = os.path.join(V, "参考", "帧"); FIN = os.path.join(V, "首帧", "定稿"); OUT = os.path.join(V, "首帧", "候选")
SIZE = "1504x2672"
NOTXT = " There is no text, caption or watermark anywhere."
STILL = "The target image is a vertical 9:16 photorealistic cinematic film still, "
KEEP = "The scene in <Picture 1> is <Subject 1>. The target image is a photorealistic cinematic film still with exactly the camera angle, framing and layout of <Picture 1>"
A_TONE = " Cold, dim, desaturated tones. Hands and faces belong to ordinary healthy people who are simply poor and tired, with smooth, normal human skin."; B_TONE = " Warm, bright golden light."
P = {
 "A1": (STILL + "close-up: inside a crumbling mud-walled hut with peeling yellow plaster, a blackened iron wok sits on a rough brick stove with a wood fire burning beneath it, orange flames lighting the underside of the wok; plain white noodles roll in boiling water, steam rising; from the upper right an ordinary middle-aged man's hand with normal healthy skin, only slightly tanned from work, enters holding a pair of old wooden chopsticks and an iron skimmer, about to lift the noodles. A single dim bare bulb overhead is the only light besides the fire." + A_TONE + NOTXT,
        "ref_1.6s.png", KEEP + ": a blackened iron wok on a brick stove over a wood fire inside a crumbling mud-walled hut, plain white noodles boiling, steam rising, and an ordinary middle-aged man's hand with normal healthy skin, only slightly tanned from work, entering from the upper right with wooden chopsticks and an iron skimmer about to lift the noodles. <Subject 1> is partially preserved: the composition, the wok, the fire, the noodles and the wall remain, while the image becomes sharper and more detailed with a plain, ordinary human hand, normal healthy skin, no cracks or deep wrinkles. All text, captions and watermarks from <Picture 1> are removed. Light comes from the fire below and a dim bare bulb above." + A_TONE),
 "A2": (STILL + "high-angle close-up: a chipped white enamel bowl with a blue rim sits on a greasy, stained old wooden table, filled with clear broth and plain white noodles, nothing else in the bowl; an ordinary man's hand with normal healthy skin enters from above pinching a small handful of chopped scallions, about to sprinkle them; dim warm light from a bare bulb above; a crumbling mud wall out of focus behind." + A_TONE + NOTXT,
        "ref_7.0s.png", KEEP + ": a chipped white enamel bowl with a blue rim on a greasy stained wooden table, clear broth and plain white noodles, an ordinary man's hand with normal healthy skin entering from above pinching chopped scallions about to sprinkle them, dim bulb light from above, mud wall behind. <Subject 1> is partially preserved: the composition, bowl, table and hand position remain, while the image becomes sharper and more detailed. All text, captions and watermarks from <Picture 1> are removed." + A_TONE),
 "A3": (STILL + "medium close-up: inside a dim mud-walled hut a bare incandescent bulb hangs on a black cord from the upper left with a thin pull-string beside it; a gaunt, deeply wrinkled middle-aged man in a worn, faded grey padded jacket sits at the right, bent over a chipped enamel bowl of plain noodles on a rough wooden table, wooden chopsticks lifting a bundle of noodles toward his slightly open mouth, numb exhausted expression, eyes on the bowl; the bulb is the only light." + A_TONE + NOTXT,
        "ref_10.5s.png", KEEP + ": a bare incandescent bulb hanging on a black cord from the upper left with a thin pull-string beside it, a gaunt deeply wrinkled middle-aged man in a worn faded grey padded jacket at the right bent over a chipped enamel bowl of plain noodles, wooden chopsticks lifting noodles toward his mouth, numb exhausted expression, mud wall behind, the bulb the only light. <Subject 1> is partially preserved: the composition, bulb, table and bowl remain, while the man becomes a different, thinner and more weathered man with the same pose. All text, captions and watermarks from <Picture 1> are removed." + A_TONE),
 "B1": (STILL + "close-up: in a bright luxury kitchen with white marble counters, a gleaming copper pan holds two large lobster tails sizzling in golden butter, a burst of orange flame licking up the side of the pan; a chef's hand in a white glove enters from the upper right holding a long spoon, about to baste butter over the lobster; blurred crystal chandelier and champagne glasses in the background." + B_TONE + NOTXT,
        "ref_1.6s.png", "<Picture 1> shows <Subject 1>, a hand lifting noodles from a wok over a fire. The target image keeps exactly the camera angle, framing and layout of <Picture 1> but changes everything in it: the blackened wok becomes a gleaming copper pan on a white marble counter in a bright luxury kitchen, the noodles become two large lobster tails sizzling in golden butter, the wood fire becomes a burst of orange flame licking up the side of the pan, the hand becomes a chef's hand in a white glove holding a long spoon about to baste butter, and the mud wall becomes a blurred crystal chandelier and champagne glasses. Photorealistic cinematic film still. All text, captions and watermarks from <Picture 1> are removed." + B_TONE),
 "B2": (STILL + "high-angle close-up: on a white tablecloth a large gold-rimmed bone-china plate holds a whole grilled lobster split open, white meat glistening with melted butter; a white-gloved hand enters from above holding a small mother-of-pearl spoon of black caviar, about to sprinkle it over the meat; a flute of bubbling champagne and silver cutlery beside the plate; blurred crystal chandelier above." + B_TONE + NOTXT,
        "ref_7.0s.png", "<Picture 1> shows <Subject 1>, a hand sprinkling scallions on a bowl of noodles. The target image keeps exactly the camera angle, framing and layout of <Picture 1> but changes everything in it: the chipped enamel bowl becomes a large gold-rimmed bone-china plate with a whole grilled lobster split open, white meat glistening with butter, the hand becomes a white-gloved hand holding a small mother-of-pearl spoon of black caviar about to sprinkle it, the stained wooden table becomes a white tablecloth with a flute of champagne and silver cutlery. Photorealistic cinematic film still. All text, captions and watermarks from <Picture 1> are removed." + B_TONE),
 "B3": (STILL + "medium close-up: in a mansion dining room a huge crystal chandelier hangs from the upper left; a relaxed, rosy-cheeked, well-fed middle-aged man in a white silk bathrobe sits at the right at a long dining table, lifting a big chunk of white lobster meat on a golden fork toward his mouth with a satisfied smile; in front of him a gold-rimmed porcelain plate with a whole grilled lobster and a flute of champagne; behind him floor-to-ceiling windows show a swimming pool under an orange sunset." + B_TONE + NOTXT,
        "ref_10.5s.png", "<Picture 1> shows <Subject 1>, a man eating noodles under a bare bulb in a mud hut. The target image keeps exactly the camera angle, framing and layout of <Picture 1> but changes everything in it: the bare bulb becomes a huge crystal chandelier hanging from the upper left; the man becomes a relaxed, rosy-cheeked, well-fed middle-aged man in a white silk bathrobe seated at the right of a long dining table in a mansion, lifting a big chunk of white lobster meat on a golden fork toward his mouth with a satisfied smile; the chipped bowl becomes a gold-rimmed porcelain plate with a whole grilled lobster and a flute of champagne beside it; the mud wall becomes floor-to-ceiling windows showing a swimming pool under an orange sunset. Photorealistic cinematic film still. All text, captions and watermarks from <Picture 1> are removed." + B_TONE),
}
EDIT = {
 "A4": ("A3.png", "<Picture 1> shows <Subject 1>, a man eating noodles under a bare bulb. The target image is identical to <Picture 1> in every way, the same man, pose, chopsticks, bowl, table, wall and framing, except that the bulb is switched off and dark: the room falls into near-total darkness, lit only by a faint cold blue glow from off to the left that dimly outlines the man's face, the chopsticks and the rim of the bowl. <Subject 1> is fully preserved. Photorealistic, very dark, cold blue-black tones."),
 "B4": ("B3.png", "<Picture 1> shows <Subject 1>, a man in a white silk bathrobe eating lobster under a chandelier. The target image keeps the same man, bathrobe, chair, table, chandelier, windows and framing as <Picture 1>, but now he leans back with a satisfied grin, the golden fork resting on the table, the first lobster plate pushed to the far left edge of the table, while a butler's white-gloved hands enter from the left setting down a fresh gold-rimmed plate with a whole new grilled lobster in front of him. <Subject 1> is partially preserved: the man, the room and the lighting remain, while his pose and the plates change. Photorealistic cinematic film still." + B_TONE),
}
arg = lambda f, d=None: sys.argv[sys.argv.index(f) + 1] if f in sys.argv else d
names = [a for a in sys.argv[1:] if a in P or a in EDIT]
mode, m, seeds = arg("--mode", "t2i"), arg("--machine", "xw"), arg("--seeds", "11,12")
env = dict(os.environ, COMFY_CLIENT_ID="mac-claude", COMFY_URL={"wj": "http://127.0.0.1:18188", "xw": "http://127.0.0.1:18189"}[m])
os.makedirs(OUT, exist_ok=True)
for n in names:
    if n in EDIT:
        img, prompt = os.path.join(FIN, EDIT[n][0]), EDIT[n][1]; tag = "edit"
    elif mode == "ref":
        img, prompt, tag = os.path.join(REF, P[n][1]), P[n][2], "ref"
    else:
        img, prompt, tag = None, P[n][0], "t2i"
    cmd = ["python3", f"{S}/h3_image.py", prompt] + (["--img", img] if img else []) + ["--size", SIZE, "--seeds", seeds, "--prefix", f"dinner/{n}_{tag}", "--wait", OUT]
    print("==", n, tag, m, flush=True)
    r = subprocess.run(cmd, env=env, capture_output=True, text=True); print(r.stdout.strip().splitlines()[-1] if r.stdout.strip() else r.stderr[-300:], flush=True)
